public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    List<Integer> inputIntegers = new ArrayList<>();

    while (sc.hasNextInt()) {
        int capture = sc.nextInt();

        if (capture == 0) {
            break;
        }

        inputIntegers.add(capture);
    }

    for (int i = inputIntegers.size() - 1; i >= 0; i--) {
        System.out.println(inputIntegers.get(i));
    }
}
